1	using UnityEngine;
2	
3	public class MuseumPlacard : MonoBehaviour
4	{
5		private bool displayActive;
6	
7		public bool useObjectNameAsDialogID;
8	
9		public string dialogID = string.Empty;
10	
11		public FacingDirection requiredFacingDirection;
12	
13		public float maxDistance = 3f;
14	
15		[HideInInspector]
16		public Player player;
17	
18		public virtual bool IsFacingPlacard => player != null && (requiredFacingDirection == FacingDirection.Neutral || requiredFacingDirection == player.facingDirection);
19	
20		public virtual void Start()
21		{
22			if (useObjectNameAsDialogID)
23			{
24				dialogID = gameObject.name;
25			}
26		}
27	
28		public virtual void Update()
29		{
30			if (!(player == null) && !(dialogID == string.Empty) && IsFacingPlacard)
31			{
32				if (Vector2.Distance(player.transform.position, transform.position) > maxDistance)
33				{
34					Exit();
35				}
36				else if (!displayActive && !DialogManager.dialogInProgress)
37				{
38					displayActive = true;
39					GameUI.dialogManager.DisplayDialog(dialogID, -1, string.Empty, string.Empty, string.Empty, isSign: true);
40				}
41			}
42		}
43	
44		public virtual void OnTriggerStay2D(Collider2D col)
45		{
46			if (player == null && col.gameObject.name == "AllyFloorContact")
47			{
48				player = col.transform.parent.gameObject.GetComponent<Player>();
49			}
50			if (displayActive && !IsFacingPlacard)
51			{
52				Exit();
53			}
54		}
55	
56		public virtual void OnTriggerExit2D(Collider2D col)
57		{
58			if (col.gameObject.name == "AllyFloorContact" && col.transform.parent.gameObject.GetComponent<Player>() != null)
59			{
60				Exit();
61			}
62		}
63	
64		public void Exit()
65		{
66			displayActive = false;
67			player = null;
68			if (DialogManager.currentDialogID == dialogID)
69			{
70				GameUI.dialogManager.ResetDialog(dialogID);
71				GameUI.dialogManager.Deactivate();
72			}
73		}
74	}
75

1	using System.Collections;
2	using Chaos.AnimatorExtensions;
3	using UnityEngine;
4	
5	public class MuseumSignatureExample : MonoBehaviour
6	{
7		public float repeatTime = 5f;
8	
9		private ChaosQuickStopwatch repeatStopwatch = new ChaosQuickStopwatch(5f);
10	
11		private Animator anim;
12	
13		private SpriteRenderer spriteRenderer;
14	
15		public Transform spawnTransform;
16	
17		private OverdriveEffects overdriveEffects;
18	
19		private Animator[] ghoulAnims = new Animator[3];
20	
21		private Material[] ghoulMats = new Material[3];
22	
23		private Vector2 leftVector = new Vector2(-1f, -1f);
24	
25		private Vector2 rightVector = new Vector2(1f, -1f);
26	
27		private bool isRight;
28	
29		private Vector2 startVector;
30	
31		private Vector2 endVector;
32	
33		private ChaosQuickStopwatch ultStopwatch = new ChaosQuickStopwatch(2f);
34	
35		private float ultLerpValue;
36	
37		private ChaosQuickStopwatch ghoulStopwatch = new ChaosQuickStopwatch();
38	
39		private FireBlast currentFB;
40	
41		private WaitForSeconds waitForFlash = new WaitForSeconds(0.03f);
42	
43		private WaitForSeconds waitForOneSecond = new WaitForSeconds(1f);
44	
45		private bool ghoulsDead;
46	
47		private AudioSource odLoopAudio;
48	
49		private void Awake()
50		{
51			anim = GetComponent<Animator>();
52			spriteRenderer = base.transform.Find("PlayerSprite").GetComponent<SpriteRenderer>();
53			spriteRenderer.material = new Material(spriteRenderer.material);
54			spriteRenderer.material.SetFloat("_PaletteIndex", 15f);
55			for (int i = 0; i < 3; i++)
56			{
57				Transform transform = base.transform.parent.Find("Ghoul" + i);
58				ghoulAnims[i] = transform.GetComponent<Animator>();
59				ghoulMats[i] = transform.Find("EnemySprite").GetComponent<SpriteRenderer>().material;
60			}
61		}
62	
63		private void Start()
64		{
65			overdriveEffects = Globals.ChaosInst<OverdriveEffects>(OverdriveEffects.Prefab, transform);
66			overdriveEffects.SetFollowTransform(transform);
67			repeatStopwatch.SetDelay(repeatTime);
68			if (spawnTransform == null)
69			{
70				spawnTransform = transform;
71			}
72		}
73	
74		private void Update()
75		{
76			if (!repeatStopwatch.IsRunning)
77			{
78				repeatStopwatch.IsRunning = true;
79				StartCoroutine(HandleFireBlast());
80			}
81		}
82	
83		private IEnumerator HandleFireBlast()
84		{
85			anim.Play("RunDown");
86			for (int i = 0; i < 3; i++)
87			{
88				ghoulAnims[i].Play("IdleDown");
89				ghoulMats[i].SetFloat("_FlashAmount", 1f);
90			}
91			yield return waitForFlash;
92			float fadeInTime = 0.25f;
93			while (fadeInTime > 0f)
94			{
95				fadeInTime -= Time.deltaTime;
96				for (int j = 0; j < 3; j++)
97				{
98					ghoulMats[j].SetFloat("_FlashAmount", Mathf.Lerp(0f, 1f, fadeInTime * 4f));
99				}
100				yield return null;
101			}
102			for (int k = 0; k < 3; k++)
103			{
104				ghoulAnims[k].Play("RunRight");
105				ghoulMats[k].SetFloat("_FlashAmount", 0f);
106			}
107			yield return waitForOneSecond;
108			anim.Play("PBAoEDown", -1, 0f);
109			while (!anim.AnimPlayed(0.3f))
110			{
111				yield return null;
112			}
113			overdriveEffects.Burst(80, local: true, activation: true, shakeCamera: false);
114			isRight = !isRight;
115			if (isRight)
116			{
117				startVector = rightVector;
118				endVector = leftVector;
119			}
120			else
121			{
122				startVector = leftVector;
123				endVector = rightVector;
124			}
125			currentFB = Globals.ChaosInst<FireBlast>(FireBlast.Prefab, spawnTransform, spawnTransform.position, Globals.GetRotationQuaternion(startVector));
126			currentFB.CircleBlast();
127			ultStopwatch.IsRunning = true;
128			ghoulStopwatch.IsRunning = true;
129			ghoulsDead = false;
130			while (ultStopwatch.IsRunning)
131			{
132				ultLerpValue = ultStopwatch.TimePercentage * 2f;
133				if (currentFB != null)
134				{
135					if (ultLerpValue <= 1f)
136					{
137						currentFB.transform.localEulerAngles = Globals.GetRotationVector(Vector2.Lerp(startVector, endVector, ultLerpValue));
138					}
139					else
140					{
141						currentFB.transform.localEulerAngles = Globals.GetRotationVector(Vector2.Lerp(endVector, startVector, ultLerpValue - 1f));
142					}
143				}
144				if (!ghoulsDead && !ghoulStopwatch.IsRunning)
145				{
146					ghoulsDead = true;
147					for (int l = 0; l < 3; l++)
148					{
149						ghoulAnims[l].Play("Dead");
150					}
151				}
152				anim.Play("PBAoEDown", -1, 0.8f);
153				PlayAudio();
154				yield return null;
155			}
156			if (currentFB != null)
157			{
158				currentFB.EndAllAttacks();
159			}
160			StopAudio();
